mapper.select:
SELECT user_key, kakao_api_id, nickname, created_at, referrer_url, system_role
FROM `user`


        (LOWER(nickname) LIKE CONCAT('%', LOWER(#{q}), '%') OR LOWER(referrer_url) LIKE CONCAT('%', LOWER(#{q}), '%'))


        AND system_role = #{role}


        AND created_at >= #{from}


        AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)


ORDER BY user_key DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM `user`


        (LOWER(nickname) LIKE CONCAT('%', LOWER(#{q}), '%') OR LOWER(referrer_url) LIKE CONCAT('%', LOWER(#{q}), '%'))


        AND system_role = #{role}


        AND created_at >= #{from}


        AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)

SELECT group_id AS groupId, name, leader_user_key AS leaderUserKey, description, capacity, created_at, auto_approve AS autoApprove, app_enabled AS appEnabled, app_name AS appName FROM `group`
LOWER(name) LIKE CONCAT('%', LOWER(#{q}), '%')
AND created_at >= #{from}
AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
ORDER BY group_id DESC LIMIT #{size} OFFSET #{offset}
